// Optional pre-recorded voice lines. Map a line id from src/story/episode01.ts to
// a file in /public/audio/voice/. Any line with a file plays that file; all other
// lines fall back to browser speech synthesis, then to subtitles only.
//
// Example:
//   n01: '/audio/voice/n01.mp3',
//
// Lines can also be generated by a server-side TTS endpoint (see docs/AUDIO.md);
// API keys must never be placed in this file or anywhere in the frontend.

export const VOICE_MANIFEST: Record<string, string> = {};
